import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import api from '../services/api';

function StudentAssignments() {
  const navigate = useNavigate();
  const [devoirs, setDevoirs] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');
  const [showSubmitModal, setShowSubmitModal] = useState(false);
  const [selectedDevoir, setSelectedDevoir] = useState(null);
  const [submissionFile, setSubmissionFile] = useState(null);
  const [submissionLoading, setSubmissionLoading] = useState(false);
  const [apiRoutes, setApiRoutes] = useState([]);

  useEffect(() => {
    const token = localStorage.getItem('token');
    if (!token) {
      navigate('/login');
      return;
    }
    fetchDevoirs();
    testApiRoutes();
  }, [navigate]);

  // Fonction pour tester les routes d'API possibles
  const testApiRoutes = async () => {
    const possibleRoutes = [
      '/api/assignments/submit',
      '/api/submit-assignment',
      '/api/assignments/submit',
      '/api/devoirs/soumettre',
      '/api/submissions',
      '/api/student/submission',
      '/api/assignment/submit'
    ];

    const availableRoutes = [];
    
    for (const route of possibleRoutes) {
      try {
        // Tester avec une requête HEAD ou GET simple
        await api.head(route);
        availableRoutes.push(route);
      } catch (error) {
        // Ignorer les erreurs 404, 405, etc.
        console.log(`Route ${route} non disponible`);
      }
    }
    
    setApiRoutes(availableRoutes);
    console.log('Routes disponibles:', availableRoutes);
  };

  const fetchDevoirs = async () => {
    try {
      setLoading(true);
      const response = await api.get('/api/student/assignments');
      setDevoirs(response.data.assignments || []);
    } catch (error) {
      console.error('Erreur chargement devoirs:', error);
      setError('Erreur lors du chargement des devoirs');
    } finally {
      setLoading(false);
    }
  };

  const handleBack = () => {
    navigate('/dashboard-student');
  };

  const getUrgencyStatus = (dateLimite) => {
    const aujourdHui = new Date();
    const limite = new Date(dateLimite);
    const diffTime = limite - aujourdHui;
    const diffDays = Math.ceil(diffTime / (1000 * 60 * 60 * 24));

    if (diffDays < 0) return { status: 'en retard', color: '#e53e3e' };
    if (diffDays <= 3) return { status: 'bientôt', color: '#ed8936' };
    return { status: 'en cours', color: '#48bb78' };
  };

  const handleDownload = async (devoirId, fileName) => {
    try {
      const response = await api.get(`/api/devoirs/${devoirId}/file`, {
        responseType: 'blob'
      });
      
      const url = window.URL.createObjectURL(new Blob([response.data]));
      const link = document.createElement('a');
      link.href = url;
      link.setAttribute('download', fileName);
      document.body.appendChild(link);
      link.click();
      link.remove();
      window.URL.revokeObjectURL(url);
    } catch (error) {
      console.error('Erreur téléchargement:', error);
      alert('Erreur lors du téléchargement du fichier');
    }
  };

  const handleSubmitWork = (devoir) => {
    setSelectedDevoir(devoir);
    setShowSubmitModal(true);
    setSubmissionFile(null);
  };

  const handleFileChange = (event) => {
    const file = event.target.files[0];
    if (file) {
      if (file.size > 10 * 1024 * 1024) {
        alert('Le fichier est trop volumineux. Taille maximale: 10MB');
        return;
      }
      setSubmissionFile(file);
    }
  };

  // Solution temporaire : Stockage local simulé
  const handleLocalSubmission = async () => {
    if (!submissionFile) {
      alert('Veuillez sélectionner un fichier à soumettre');
      return;
    }

    try {
      setSubmissionLoading(true);

      // Simulation de soumission - stockage local
      const submission = {
        devoirId: selectedDevoir.id,
        devoirTitle: selectedDevoir.title,
        fileName: submissionFile.name,
        fileSize: submissionFile.size,
        submittedAt: new Date().toISOString(),
        status: 'soumis'
      };

      // Stocker dans localStorage
      const existingSubmissions = JSON.parse(localStorage.getItem('devoirSubmissions') || '[]');
      existingSubmissions.push(submission);
      localStorage.setItem('devoirSubmissions', JSON.stringify(existingSubmissions));

      console.log('Soumission simulée:', submission);

      alert('✅ Devoir soumis avec succès! (Stockage local)');
      setShowSubmitModal(false);
      setSelectedDevoir(null);
      setSubmissionFile(null);
      
      // Mettre à jour l'interface
      fetchDevoirs();

    } catch (error) {
      console.error('Erreur soumission locale:', error);
      alert('Erreur lors de la soumission simulée');
    } finally {
      setSubmissionLoading(false);
    }
  };

  // Essai avec différentes routes d'API
  const handleApiSubmission = async () => {
    if (!submissionFile) {
      alert('Veuillez sélectionner un fichier à soumettre');
      return;
    }

    try {
      setSubmissionLoading(true);

      const formData = new FormData();
      formData.append('file', submissionFile);
      formData.append('devoir_id', selectedDevoir.id);
      formData.append('assignment_id', selectedDevoir.id);

      const token = localStorage.getItem('token');
      let response;
      let success = false;

      // Essayer différentes routes
      const routesToTry = [
        '/api/student/assignments/submit',
        '/api/student/submit-assignment', 
        '/api/assignments/submit',
        '/api/devoirs/soumettre',
        '/api/submissions',
        '/api/assignment/submit'
      ];

      for (const route of routesToTry) {
        try {
          console.log(`Essai de soumission via: ${route}`);
          response = await fetch(route, {
            method: 'POST',
            headers: {
              'Authorization': `Bearer ${token}`,
            },
            body: formData,
          });

          if (response.ok) {
            success = true;
            console.log(`✅ Succès avec la route: ${route}`);
            break;
          } else {
            console.log(`❌ Échec avec ${route}: ${response.status}`);
          }
        } catch (error) {
          console.log(`❌ Erreur avec ${route}:`, error.message);
        }
      }

      if (success) {
        const result = await response.json();
        console.log('Soumission réussie:', result);
        alert('✅ Devoir soumis avec succès!');
        setShowSubmitModal(false);
        setSelectedDevoir(null);
        setSubmissionFile(null);
        fetchDevoirs();
      } else {
        throw new Error('Aucune route API valide trouvée');
      }

    } catch (error) {
      console.error('Erreur soumission API:', error);
      
      // Proposer la solution locale en fallback
      const useLocal = confirm(
        `Impossible de contacter le serveur pour la soumission.\n\n` +
        `Erreur: ${error.message}\n\n` +
        `Voulez-vous sauvegarder localement en attendant ?\n` +
        `(Votre professeur ne pourra pas voir cette soumission)`
      );
      
      if (useLocal) {
        handleLocalSubmission();
      }
    } finally {
      setSubmissionLoading(false);
    }
  };

  const closeModal = () => {
    setShowSubmitModal(false);
    setSelectedDevoir(null);
    setSubmissionFile(null);
  };

  // Vérifier si un devoir a été soumis (localement)
  const isDevoirSubmitted = (devoirId) => {
    const submissions = JSON.parse(localStorage.getItem('devoirSubmissions') || '[]');
    return submissions.some(sub => sub.devoirId === devoirId);
  };

  if (loading) {
    return (
      <div style={styles.loadingContainer}>
        <div style={styles.spinner}></div>
        <p>Chargement de vos devoirs...</p>
      </div>
    );
  }

  return (
    <div style={styles.container}>
      <header style={styles.header}>
        <button onClick={handleBack} style={styles.backButton}>
          ← Retour au Dashboard
        </button>
        <h1 style={styles.title}>Mes Devoirs</h1>
        <div style={styles.headerActions}>
          <span style={styles.counter}>
            {devoirs.length} devoir{devoirs.length > 1 ? 's' : ''}
          </span>
        </div>
      </header>

      <main style={styles.main}>
        {error && (
          <div style={styles.errorAlert}>
            {error}
          </div>
        )}

        {/* Bannière d'information sur le mode local */}
        {apiRoutes.length === 0 && (
          <div style={styles.warningBanner}>
            <strong>Mode démo activé</strong> - Les soumissions seront sauvegardées localement
          </div>
        )}

        {devoirs.length === 0 ? (
          <div style={styles.emptyState}>
            <div style={styles.emptyIcon}>📝</div>
            <h3>Aucun devoir disponible</h3>
            <p>Vos devoirs apparaîtront ici une fois assignés par vos professeurs.</p>
          </div>
        ) : (
          <div style={styles.assignmentsGrid}>
            {devoirs.map((devoir) => {
              const urgency = getUrgencyStatus(devoir.date_limite);
              const isOverdue = new Date(devoir.date_limite) < new Date();
              const isSubmitted = isDevoirSubmitted(devoir.id);
              
              return (
                <div key={devoir.id} style={styles.assignmentCard}>
                  <div style={styles.assignmentHeader}>
                    <h3 style={styles.assignmentTitle}>{devoir.title}</h3>
                    <div style={styles.headerBadges}>
                      <span style={{
                        ...styles.urgencyBadge,
                        background: urgency.color
                      }}>
                        {urgency.status}
                      </span>
                      {isSubmitted && (
                        <span style={styles.submittedBadge}>
                          ✅ Soumis
                        </span>
                      )}
                    </div>
                  </div>
                  
                  <div style={styles.assignmentInfo}>
                    <p style={styles.assignmentDescription}>
                      {devoir.description || 'Aucune description disponible'}
                    </p>
                    
                    <div style={styles.assignmentMeta}>
                      <div style={styles.metaItem}>
                        <strong>Cours:</strong> {devoir.course_title}
                      </div>
                      <div style={styles.metaItem}>
                        <strong>Professeur:</strong> {devoir.professeur_nom}
                      </div>
                      <div style={styles.metaItem}>
                        <strong>Date limite:</strong> 
                        <span style={{
                          color: urgency.color,
                          fontWeight: '600',
                          marginLeft: '0.5rem'
                        }}>
                          {new Date(devoir.date_limite).toLocaleDateString('fr-FR')}
                        </span>
                      </div>
                      <div style={styles.metaItem}>
                        <strong>Statut:</strong> 
                        <span style={{
                          color: isSubmitted ? '#48bb78' : 
                                 isOverdue ? '#e53e3e' : '#718096',
                          fontWeight: '600',
                          marginLeft: '0.5rem'
                        }}>
                          {isSubmitted ? 'Soumis (local)' : 
                           isOverdue ? 'En retard' : 'Non soumis'}
                        </span>
                      </div>
                    </div>
                  </div>

                  <div style={styles.assignmentActions}>
                    {devoir.fichier && (
                      <button
                        onClick={() => handleDownload(devoir.id, devoir.fichier)}
                        style={styles.downloadButton}
                      >
                        📥 Télécharger le devoir
                      </button>
                    )}
                    <button 
                      onClick={() => handleSubmitWork(devoir)}
                      style={{
                        ...styles.submitButton,
                        background: isOverdue ? '#a0aec0' : 
                                   isSubmitted ? '#38a169' : '#48bb78',
                        cursor: isOverdue ? 'not-allowed' : 'pointer'
                      }}
                      disabled={isOverdue}
                      title={isOverdue ? "La date limite est dépassée" : 
                             isSubmitted ? "Déjà soumis" : "Soumettre votre travail"}
                    >
                      {isOverdue ? '⏰ Date dépassée' : 
                       isSubmitted ? '✅ Déjà soumis' : '📤 Soumettre ma copie'}
                    </button>
                  </div>
                </div>
              );
            })}
          </div>
        )}
      </main>

      {/* Modal de soumission */}
      {showSubmitModal && selectedDevoir && (
        <div style={styles.modalOverlay}>
          <div style={styles.modal}>
            <div style={styles.modalHeader}>
              <h2 style={styles.modalTitle}>Soumettre mon travail</h2>
              <button onClick={closeModal} style={styles.closeButton}>×</button>
            </div>
            
            <div style={styles.modalBody}>
              <div style={styles.assignmentInfoModal}>
                <h4>{selectedDevoir.title}</h4>
                <p><strong>Date limite:</strong> {new Date(selectedDevoir.date_limite).toLocaleDateString('fr-FR')}</p>
                <p style={{
                  color: getUrgencyStatus(selectedDevoir.date_limite).color,
                  fontWeight: '600'
                }}>
                  Statut: {getUrgencyStatus(selectedDevoir.date_limite).status}
                </p>
              </div>

              <div style={styles.fileUploadSection}>
                <label style={styles.fileUploadLabel}>
                  📎 Choisir votre fichier
                  <input
                    type="file"
                    onChange={handleFileChange}
                    style={styles.fileInput}
                    accept=".pdf,.doc,.docx,.txt,.jpg,.jpeg,.png"
                  />
                </label>
                
                {submissionFile && (
                  <div style={styles.fileInfo}>
                    <span>📄 {submissionFile.name}</span>
                    <span style={styles.fileSize}>
                      ({(submissionFile.size / 1024 / 1024).toFixed(2)} MB)
                    </span>
                  </div>
                )}
                
                <div style={styles.uploadTips}>
                  <p><strong>Formats acceptés:</strong> PDF, Word, TXT, JPG, PNG</p>
                  <p><strong>Taille maximale:</strong> 10MB</p>
                </div>
              </div>

              {/* Information sur le mode de soumission */}
              <div style={styles.modeInfo}>
                <p style={styles.modeText}>
                  <strong>Mode:</strong> {apiRoutes.length > 0 ? 'Connexion API' : 'Stockage local'}
                </p>
                {apiRoutes.length === 0 && (
                  <p style={styles.localWarning}>
                    ⚠️ Les soumissions seront sauvegardées localement uniquement.
                    Votre professeur ne pourra pas voir cette soumission.
                  </p>
                )}
              </div>
            </div>

            <div style={styles.modalActions}>
              <button 
                onClick={closeModal}
                style={styles.cancelButton}
                disabled={submissionLoading}
              >
                Annuler
              </button>
              <button 
                onClick={apiRoutes.length > 0 ? handleApiSubmission : handleLocalSubmission}
                style={{
                  ...styles.confirmButton,
                  background: !submissionFile || submissionLoading ? '#a0aec0' : 
                             apiRoutes.length > 0 ? '#48bb78' : '#ed8936'
                }}
                disabled={!submissionFile || submissionLoading}
              >
                {submissionLoading ? (
                  <>
                    <div style={styles.smallSpinner}></div>
                    Soumission en cours...
                  </>
                ) : apiRoutes.length > 0 ? 'Soumettre' : 'Sauvegarder localement'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const styles = {
  // ... (garder tous les styles précédents et ajouter les nouveaux)
  warningBanner: {
    background: '#fffaf0',
    border: '1px solid #ed8936',
    color: '#c05621',
    padding: '1rem',
    borderRadius: '8px',
    marginBottom: '1rem',
    textAlign: 'center',
  },
  headerBadges: {
    display: 'flex',
    gap: '0.5rem',
    flexDirection: 'column',
    alignItems: 'flex-end',
  },
  submittedBadge: {
    background: '#48bb78',
    color: 'white',
    padding: '0.25rem 0.75rem',
    borderRadius: '12px',
    fontSize: '0.8rem',
    fontWeight: '600',
  },
  modeInfo: {
    background: '#f7fafc',
    padding: '1rem',
    borderRadius: '8px',
    marginTop: '1rem',
  },
  modeText: {
    margin: '0 0 0.5rem 0',
    fontSize: '0.9rem',
    color: '#4a5568',
  },
  localWarning: {
    margin: 0,
    fontSize: '0.8rem',
    color: '#ed8936',
    fontStyle: 'italic',
  },
  // ... (autres styles)
};

export default StudentAssignments;
